ecent=new WP_Query(['posts_per_page'=>3,'offset'=>5]); while($recent->have_posts()):$recent->the_post(); ?><article class="text-story"><span class="kicker"><?php echo esc_html(jnt_category()); ?></span><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p><span class="byline"><?php echo esc_html(get_the_date()); ?></span></article><?php endwhile; wp_reset_postdata(); ?></div></section><section class="newsletter"><div><span class="eyebrow">NEWSLETTER</span><h2>Notícias que aproximam.</h2><p>Receba a seleção semanal na sua caixa de entrada.</p></div><?php get_search_form(); ?></section></main><?php get_footer(); ?>